def to_system(answer, order):
    if answer == "tie":
        return "tie"
    first, second = ("X", "Y") if order == "xy" else ("Y", "X")
    return first if answer == "A" else second

record = {"xy": "B", "yx": "A"}
a, b = to_system(record["xy"], "xy"), to_system(record["yx"], "yx")
print(a if a == b and a != "tie" else "tie")

def judge_accuracy(examples, verdicts):
    """examples: list of (id, human_label); verdicts: dict id -> "pass", "fail", or None."""
    correct = 0
    for ex_id, human in examples:
        judged = verdicts.get(ex_id) or "fail"
        correct += judged == human
    return correct / len(examples)
